#include "goal1_native_boundary_history.hpp"
#include "goal1_native_pulse_oracle.hpp"
#include "goal1_native_face_boundary.hpp"
#include <iostream>
#include <iomanip>
namespace cs=cubed_sphere;namespace bh=cs::native_boundary_history;namespace h=z4c::hyperboloidal;
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int status=0;std::cout<<std::setprecision(17);try{int id;Real x[3],amp,width;while(std::cin>>id>>x[0]>>x[1]>>x[2]>>amp>>width){auto a=bh::Build(x,amp,width),z=bh::Build(x,amp,width,.123);Real missing=0;std::vector<Real>flat;cs::typed_support::Map<Real>(z.second,[&](int,Real v){flat.push_back(v);return v;});cs::typed_support::Map<Real>(a.second,[&](int i,Real v){missing=std::max(missing,std::abs(v-flat[i]));return v;});h::LayerReference<Real>descriptor(1.,.5,{true,.05,.95});auto p=descriptor.At(x[0],x[1],x[2]);auto old=cs::native_pulse_oracle::Deviation(x,amp,width);h::AddBackgroundJet(old,p.state);std::vector<Real>prior;cs::typed_support::Map<Real>(old,[&](int,Real v){prior.push_back(v);return v;});Real initial=0;cs::typed_support::Map<Real>(a.initial,[&](int i,Real v){initial=std::max(initial,std::abs(v-prior[i]));return v;});Real n[3],norm=0;for(auto v:x)norm+=v*v;norm=std::sqrt(norm);for(int i=0;i<3;++i)n[i]=x[i]/norm;cs::native_face_boundary::Boundary b;if(!b.Build(a.initial,n,p.omega))throw std::runtime_error("initial boundary invalid");Real rows[10];b.Rows(a.initial,p.state,rows);
 std::cout<<"{\"id\":"<<id<<",\"xyz\":["<<x[0]<<","<<x[1]<<","<<x[2]<<"],\"initial_oracle_difference\":"<<initial<<",\"raw_reference_RHS\":"<<a.raw_reference_RHS<<",\"source_spatial_chain_error\":"<<a.source_gradient_error<<",\"unprovided_higherjet_influence\":"<<missing<<",\"initial_rows\":[";for(int i=0;i<10;++i)std::cout<<(i?",":"")<<rows[i];std::cout<<"],\"coefficients\":[";for(int order=0;order<=2;++order){if(order)std::cout<<",";auto&u=order==0?a.initial:(order==1?a.first:a.second);std::cout<<"[";for(int j=0;j<22;++j){auto s=cs::operator_oracle::Component(u,j);if(j)std::cout<<",";std::cout<<"["<<s.value;for(int d=0;d<3;++d)std::cout<<","<<s.d[d];for(int d=0;d<3;++d)for(int e=0;e<3;++e)std::cout<<","<<s.dd[d][e];std::cout<<"]";}std::cout<<"]";}std::cout<<"]}"<<std::endl;
 }}catch(const std::exception&e){std::cerr<<e.what()<<'\n';status=1;}Kokkos::finalize();return status;}
